import{_ as d,o,c as e,ag as r}from"./chunks/framework.KxDd3USm.js";const g=JSON.parse('{"title":"06.7 HTML、WWW 与网络命令 ★","description":"","frontmatter":{},"headers":[],"relativePath":"06-计算机网络/07-Web与网络命令.md","filePath":"06-计算机网络/07-Web与网络命令.md"}'),a={name:"06-计算机网络/07-Web与网络命令.md"};function n(s,t,l,c,h,p){return o(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="_06-7-html、www-与网络命令-★" tabindex="-1">06.7 HTML、WWW 与网络命令 ★ <a class="header-anchor" href="#_06-7-html、www-与网络命令-★" aria-label="Permalink to &quot;06.7 HTML、WWW 与网络命令 ★&quot;">​</a></h1><h3 id="www-三要素" tabindex="-1">WWW 三要素 <a class="header-anchor" href="#www-三要素" aria-label="Permalink to &quot;WWW 三要素&quot;">​</a></h3><p>万维网（WWW）由三样东西撑起来，三者名字要能配对：</p><table tabindex="0"><thead><tr><th>要素</th><th>作用</th><th>关键词</th></tr></thead><tbody><tr><td><strong>URL</strong>（统一资源定位符）</td><td>给每个资源一个全球唯一&quot;门牌号&quot;</td><td>协议://主机:端口/路径</td></tr><tr><td><strong>HTML</strong>（超文本标记语言）</td><td>写网页的语言，用<strong>标签</strong>标记内容与结构</td><td>标签、超链接</td></tr><tr><td><strong>HTTP</strong></td><td>浏览器与 Web 服务器之间传输网页的协议</td><td>请求/响应，默认 80 端口</td></tr></tbody></table><p>例：<code>http://www.example.com:8080/exam/index.html</code>——协议 <code>http</code>，主机 <code>www.example.com</code>，端口 <code>8080</code>（省略时 HTTP 默认 80），路径 <code>/exam/index.html</code>。</p><h3 id="url-与域名-从右向左看层级-★★" tabindex="-1">URL 与域名：从右向左看层级 ★★ <a class="header-anchor" href="#url-与域名-从右向左看层级-★★" aria-label="Permalink to &quot;URL 与域名：从右向左看层级 ★★&quot;">​</a></h3><p>URL 的通用形式可写为：</p><blockquote><p><strong>协议://主机名:端口/路径?查询参数</strong></p></blockquote><p>以 <code>https://www.example.com:443/search?q=network</code> 为例：</p><table tabindex="0"><thead><tr><th>部分</th><th>内容</th><th>作用</th></tr></thead><tbody><tr><td>协议</td><td><code>https</code></td><td>规定浏览器与服务器怎样通信</td></tr><tr><td>主机名</td><td><code>www.example.com</code></td><td>指定要访问的网络主机</td></tr><tr><td>端口</td><td><code>443</code></td><td>指定主机上的服务进程；HTTPS 默认端口，可省略</td></tr><tr><td>路径</td><td><code>/search</code></td><td>指定服务器上的资源或处理入口</td></tr><tr><td>查询参数</td><td><code>q=network</code></td><td>把附加条件交给服务器</td></tr></tbody></table><p>域名按点分层，<strong>越靠右层级越高</strong>。以 <code>www.example.com</code> 为例，从右向左看：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.（根域，通常省略）</span></span>
<span class="line"><span>└── com        顶级域</span></span>
<span class="line"><span>    └── example  注册域/二级域</span></span>
<span class="line"><span>        └── www    主机名标签</span></span></code></pre></div><p>日常题目常把完整的 <code>www.example.com</code> 称为主机名（完整限定域名）。<code>https</code> 不是主机名，<code>/search</code> 也不是；看到“URL 中的主机”就取 <code>://</code> 后、端口或第一个 <code>/</code> 前的部分。</p><p><strong>反例演示</strong>：把 <code>www</code> 单独答成完整主机名通常不够；它只是域名最左侧的主机标签，离开 <code>example.com</code> 无法全球唯一定位。</p><h3 id="dns-域名怎样变成-ip-故障怎样判断-★★" tabindex="-1">DNS：域名怎样变成 IP，故障怎样判断 ★★ <a class="header-anchor" href="#dns-域名怎样变成-ip-故障怎样判断-★★" aria-label="Permalink to &quot;DNS：域名怎样变成 IP，故障怎样判断 ★★&quot;">​</a></h3><p>人容易记 <code>www.example.com</code>，网络转发却依靠 IP。<strong>DNS 的任务是把域名解析成 IP 地址</strong>。浏览器通常先查本机缓存；没有结果再向配置的 DNS 服务器查询，拿到 IP 后才建立传输层连接。</p><p>常见现象可以这样定位：</p><table tabindex="0"><thead><tr><th>现象</th><th>优先怀疑</th><th>判断依据</th></tr></thead><tbody><tr><td>能访问某公网 IP，却打不开任何域名</td><td><strong>DNS 配置或解析故障</strong></td><td>IP 连通说明基本链路可用，失败集中在“名字变 IP”</td></tr><tr><td>同网段能通，所有外网 IP 都不通</td><td><strong>默认网关/路由</strong></td><td>本地链路正常，跨网第一跳失败</td></tr><tr><td>IP 和域名都不通，网关也 ping 不通</td><td>本机配置、网卡、链路或网关</td><td>还没到 DNS 阶段</td></tr><tr><td>只有一个网站打不开，其他网站正常</td><td>该站服务器、该域名记录或访问策略</td><td>不能据此断定本机 DNS 整体损坏</td></tr></tbody></table><p><code>nslookup 域名</code>用于直接检查 DNS 解析；<code>ping IP</code>与<code>ping 域名</code>组合测试，能帮助区分“网络不通”还是“只解析失败”。注意：部分服务器会禁用 ping，因此 ping 不通不能单独证明网站服务宕机，题目若给出多条现象要综合判断。</p><h3 id="http-请求-get-与-post-怎么区分-★★" tabindex="-1">HTTP 请求：GET 与 POST 怎么区分 ★★ <a class="header-anchor" href="#http-请求-get-与-post-怎么区分-★★" aria-label="Permalink to &quot;HTTP 请求：GET 与 POST 怎么区分 ★★&quot;">​</a></h3><p>HTTP 采用“请求—响应”模式。浏览器先发送请求行、首部和可选的消息体，服务器再返回状态、首部和内容。考试常比较 GET 与 POST：</p><table tabindex="0"><thead><tr><th>对比项</th><th>GET</th><th>POST</th></tr></thead><tbody><tr><td>典型用途</td><td>获取/查询资源</td><td>提交数据、创建或修改资源</td></tr><tr><td>参数常见位置</td><td>URL 查询串，如 <code>?page=2</code></td><td>请求体</td></tr><tr><td>收藏与分享</td><td>带查询参数的 URL 易收藏、分享</td><td>请求体不会随普通书签保存</td></tr><tr><td>缓存</td><td>更适合缓存</td><td>通常不按普通查询缓存</td></tr><tr><td>典型场景</td><td>搜索、查看列表</td><td>登录表单、提交订单、上传数据</td></tr></tbody></table><p><strong>最重要的反例</strong>：“POST 的参数不出现在地址栏，所以 POST 天然加密”——错。GET 和 POST 都只是 HTTP 方法；若使用明文 HTTP，传输内容都可能被窃听。需要保密性与完整性必须使用 <strong>HTTPS</strong>。</p><p><strong>应试动作</strong>：题干出现“获取、查询、可收藏 URL”优先选 GET；出现“提交表单、改变服务器状态、请求体”优先选 POST。不要把“参数位置”误记成“是否加密”。</p><h3 id="静态网页、动态网页与浏览器职责-★★" tabindex="-1">静态网页、动态网页与浏览器职责 ★★ <a class="header-anchor" href="#静态网页、动态网页与浏览器职责-★★" aria-label="Permalink to &quot;静态网页、动态网页与浏览器职责 ★★&quot;">​</a></h3><ul><li><strong>静态网页</strong>：服务器通常直接返回已保存的 HTML/CSS/图片文件；同一资源对不同访客的主体内容基本相同。</li><li><strong>动态网页</strong>：服务器根据请求参数、登录用户、数据库内容等在运行时生成结果，例如查询成绩、购物车和订单页面。服务器可能使用 PHP、Java、Python 等程序处理，但发给浏览器的最终结果仍通常是 HTML、JSON、图片等可传输内容。</li><li><strong>客户端动态效果</strong>：JavaScript 也可在浏览器中修改页面或再次请求数据。它和“服务器端动态生成”不是同一位置的处理，但都能让页面随操作变化。</li></ul><p>浏览器不是只“显示 HTML”：它先解析 URL、借助 DNS 找 IP、建立连接、发送 HTTP 请求，再解析 HTML/CSS、执行必要脚本并渲染页面。服务器负责处理请求和返回资源，浏览器负责解释与呈现收到的内容。</p><p><strong>故障链定位口诀</strong>：<strong>先地址，再解析；再连接，再请求；有响应，看状态；有内容，看渲染。</strong></p><ol><li>URL 格式或主机名写错：请求还没找到正确目标。</li><li>DNS 失败：域名无法变成 IP。</li><li>TCP/端口连接失败：服务器未监听、网络路径或防火墙可能有问题。</li><li>HTTP 返回 404：已联系服务器，但请求资源不存在；这不是 DNS 故障。</li><li>服务器返回正常而页面显示异常：再查 HTML/CSS/JavaScript 或浏览器兼容问题。</li></ol><h3 id="html-常识-考选择题的粒度" tabindex="-1">HTML 常识（考选择题的粒度） <a class="header-anchor" href="#html-常识-考选择题的粒度" aria-label="Permalink to &quot;HTML 常识（考选择题的粒度）&quot;">​</a></h3><ul><li>HTML 用<strong>标签</strong>写文档，形如 <code>&lt;标签名&gt;…&lt;/标签名&gt;</code>，浏览器负责<strong>解析 HTML 并渲染</strong>成页面；HTML 是标记语言，不是编程语言。</li><li><strong>超链接</strong>：<code>&lt;a href=&quot;http://www.example.com&quot;&gt;链接文字&lt;/a&gt;</code>——考题问&quot;网页中建立超链接的标签&quot;答 <strong><code>&lt;a&gt;</code>（href 属性）</strong>。</li><li>常见标签识别：<code>&lt;html&gt;</code> 根标签；<code>&lt;head&gt;</code> 头部信息（标题等，不显示在正文）；<code>&lt;body&gt;</code> 正文；<code>&lt;img src=&quot;…&quot;&gt;</code> 插入图片；<code>&lt;br&gt;</code> 换行；<code>&lt;p&gt;</code> 段落。</li><li>浏览器访问网页的完整链路：URL → DNS 把域名解析成 IP → 与服务器端口建立 TCP 连接 → 发 HTTP 请求 → 服务器返回 HTML 等内容 → 浏览器解析并渲染。HTTP 默认 80，HTTPS 默认 443。</li></ul><h3 id="常用网络命令-偶尔考一道常识题" tabindex="-1">常用网络命令（偶尔考一道常识题） <a class="header-anchor" href="#常用网络命令-偶尔考一道常识题" aria-label="Permalink to &quot;常用网络命令（偶尔考一道常识题）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><strong>ping</strong></td><td>测试与目标主机的<strong>连通性</strong>（基于 ICMP）</td></tr><tr><td><strong>ipconfig</strong>（Windows）</td><td>查看本机 IP 配置；<code>ipconfig /all</code> 还显示 MAC 地址、DNS、DHCP 租约等</td></tr><tr><td><strong>tracert</strong></td><td>跟踪到目标沿途经过的<strong>路由路径</strong></td></tr><tr><td><strong>netstat</strong></td><td>查看本机的网络连接与端口占用状态</td></tr><tr><td><strong>nslookup</strong></td><td>手动查询 DNS 解析结果</td></tr><tr><td><strong>arp</strong></td><td>查看/维护 IP 地址与 MAC 地址的对应表</td></tr></tbody></table><p><strong>应试动作</strong>：① WWW 三要素配对（URL 门牌、HTML 语言、HTTP 协议）；② 能从 URL 圈出协议、完整主机名、端口、路径和参数；③ 会用“IP 能通、域名不通”识别 DNS 故障，用“同网能通、外网不通”检查网关；④ GET/POST 看用途与参数位置，不能拿它们判断是否加密；⑤ 命令按用途配对背：连通性 ping、路径 tracert、本机配置 ipconfig、连接状态 netstat、解析检查 nslookup。</p><hr>`,35)])])}const T=d(a,[["render",n]]);export{g as __pageData,T as default};
